    "content": "package com.smartlib.entity;\n\n/**\n * User roles within the SmartLib system.\n * Spring Security maps these as 'ROLE_USER' and 'ROLE_ADMIN'.\n */\npublic enum Role {\n    USER,\n    ADMIN\n}\n"
